class Solution {
    public int longestCommonPrefix(int[] arr1,int[] arr2){
        Set<Integer> prefixes=new HashSet<>();
        for(int number:arr1)for(int value=number;value>0;value/=10)prefixes.add(value);
        int answer=0;
        for(int number:arr2){
            int value=number,length=Integer.toString(number).length();
            while(value>0&&length>answer){
                if(prefixes.contains(value)){
                    answer=length;
                    break;
                }
                value/=10;
                length--;
            }
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun longestCommonPrefix(arr1:IntArray,arr2:IntArray):Int{
        val prefixes=HashSet<Int>();
        for(number in arr1){
            var value=number;
            while(value>0){
                prefixes.add(value);
                value/=10
            }
        };
        var answer=0;
        for(number in arr2){
            var value=number;
            var length=number.toString().length;
            while(value>0&&length>answer){
                if(value in prefixes){
                    answer=length;
                    break
                };
                value/=10;
                length--
            }
        };
        return answer
    }
}

